// ============ Resolve Cursor (fallback = NOW - CURSOR_FALLBACK_HOURS) ============
// Empty/missing cursor → default to (now - N hours). Prevents a first-run scanning
// the entire store. Passed to Fetch Orders as updated_at_min.

const params = $('Set Parameters').first().json;
const rows = $('Read Cursor').all().map(it => it.json).filter(r => r && Object.keys(r).length > 0);

let cursor = '';
for (const r of rows) {
  const keys = Object.keys(r).filter(k => k !== 'row_number');
  const v = keys.length ? String(r[keys[0]] || '').trim() : '';
  if (v && !/^last_processed_iso$/i.test(v)) { cursor = v; break; }
}

if (!cursor) {
  const fallbackHours = parseFloat(params.CURSOR_FALLBACK_HOURS || '1') || 1;
  const d = new Date(Date.now() - fallbackHours * 3600 * 1000);
  cursor = d.toISOString();
}

return [{ json: { cursor } }];

// ============ Build Grant Intents ============
// For each paid order × line item, match SKU against Folder Grants (Active=TRUE),
// pull customer email, dedup within batch AND against Folder Grants Log.
// Also compute batch_max_updated_at for cursor advancement (regardless of matches).

function escRegex(s) { return String(s).replace(/[.+?^${}()|[\]\\]/g, '\\$&'); }

// Enhanced placeholder rule (vs v5's XXX-only, case-sensitive): match COLOUR (any case)
// or any run of 3+ x's / X's. Handles MegaSMC-3dparts-BRT-XXXX, MegaSMC-3dparts-CQB-xxxx,
// gfz-sbl2-COLOUR, etc. — treats -/_ interchangeably, case-insensitive final match.
function skuToRegex(sku) {
  const pat = '^' + escRegex(sku)
    .replace(/COLOUR/gi, '.+')
    .replace(/x{3,}/gi, '.+')
    .replace(/[-_]/g, '[-_]') + '$';
  return new RegExp(pat, 'i');
}

// ----- Load Folder Grants (active rows only) -----
const grantsRaw = $('Read Folder Grants').all().map(it => it.json);
const grants = [];
for (const r of grantsRaw) {
  const sku = String(r['SKU'] || '').trim();
  const folderId = String(r['Folder ID'] || '').trim();
  if (!sku || !folderId) continue;
  const active = String(r['Active'] || '').trim().toUpperCase();
  if (active && active !== 'TRUE') continue;
  grants.push({
    sku,
    folder_id: folderId,
    folder_name: String(r['Folder Name'] || '').trim(),
    role: (String(r['Role'] || 'reader').trim().toLowerCase()) || 'reader',
    re: skuToRegex(sku),
  });
}

// ----- Load existing Log for dedup (SHARED + ALREADY_SHARED count as done) -----
const logRaw = $('Read Folder Grants Log').all().map(it => it.json);
const doneKeys = new Set();
for (const r of logRaw) {
  const status = String(r['Status'] || '').trim().toUpperCase();
  if (status !== 'SHARED' && status !== 'ALREADY_SHARED') continue;
  const orderNo = String(r['Order No'] || '').trim();
  const email = String(r['Customer Email'] || '').trim().toLowerCase();
  const folderId = String(r['Folder ID'] || '').trim();
  if (!orderNo || !email || !folderId) continue;
  doneKeys.add(orderNo + '|' + email + '|' + folderId);
}

// ----- Fetch orders -----
const pages = $('Fetch Orders (paginated)').all();
const orders = pages.flatMap(p => (p.json && p.json.orders) ? p.json.orders : []);

// ----- Compute batch_max_updated_at for cursor -----
let maxUpdatedMs = 0;
for (const o of orders) {
  const t = Date.parse(o.updated_at || o.created_at || '');
  if (!isNaN(t) && t > maxUpdatedMs) maxUpdatedMs = t;
}
const batchMaxIso = maxUpdatedMs > 0 ? new Date(maxUpdatedMs + 1000).toISOString() : ''; // +1s to avoid re-fetching the same row next tick

// ----- Build intents -----
const intents = [];
const seenBatch = new Set();
for (const o of orders) {
  const orderNo = o.order_number != null ? String(o.order_number) : String(o.name || '').replace('#','');
  const email = String((o.customer && o.customer.email) || o.email || o.contact_email || '').trim().toLowerCase();
  const orderUpdatedAt = o.updated_at || o.created_at || '';

  for (const li of (o.line_items || [])) {
    const sku = String(li.sku || '').trim();
    if (!sku) continue;
    const matched = grants.filter(g => g.re.test(sku));
    if (matched.length === 0) continue;

    for (const g of matched) {
      // Missing email → log ERROR row with no Drive call
      if (!email) {
        const k = orderNo + '|NOEMAIL|' + g.folder_id;
        if (seenBatch.has(k)) continue;
        seenBatch.add(k);
        intents.push({
          order_no: orderNo,
          sku,
          email: '',
          folder_id: g.folder_id,
          folder_name: g.folder_name,
          role: g.role,
          order_updated_at: orderUpdatedAt,
          _skip_reason: 'no email on order',
        });
        continue;
      }

      const key = orderNo + '|' + email + '|' + g.folder_id;
      if (seenBatch.has(key)) continue;
      if (doneKeys.has(key)) continue;
      seenBatch.add(key);

      intents.push({
        order_no: orderNo,
        sku,
        email,
        folder_id: g.folder_id,
        folder_name: g.folder_name,
        role: g.role,
        order_updated_at: orderUpdatedAt,
      });
    }
  }
}

const dbg = {
  orders_fetched: orders.length,
  active_grants: grants.length,
  done_keys_loaded: doneKeys.size,
  intents_built: intents.length,
  batch_max_updated_iso: batchMaxIso,
};
console.log('[folder-grant intents]', JSON.stringify(dbg));

// Always emit at least one item so downstream nodes fire (cursor still advances
// even when 0 intents matched). Sentinel item carries only the cursor.
if (intents.length === 0) {
  return [{ json: { _sentinel: true, batch_max_updated_iso: batchMaxIso } }];
}
// Attach batch cursor to every intent so the grant node can pick it up regardless of order
return intents.map(i => ({ json: { ...i, batch_max_updated_iso: batchMaxIso } }));

// ============ Grant + Log + Advance Cursor ============
// Signs one JWT (dual scope: sheets + drive), then:
//  (a) For each real intent → POST to Drive permissions.create (sendNotificationEmail=true),
//      Google emails the customer the standard 'shared with you' notice.
//  (b) Appends one Folder Grants Log row per intent (SHARED / ALREADY_SHARED / ERROR /
//      NO_EMAIL). Sentinel-only batches skip (a) and (b).
//  (c) Overwrites Folder Grants Cursor!A2 with batch_max_updated_iso (only if > current).
// Cursor advances only AFTER log append succeeds so we never lose an order on partial failure.

const fs = require('fs');
const crypto = require('crypto');
const https = require('https');

function b64u(buf) { return Buffer.from(buf).toString('base64').replace(/=+$/,'').replace(/\+/g,'-').replace(/\//g,'_'); }
function signJWT(saJson, scope) {
  const now = Math.floor(Date.now() / 1000);
  const header  = { alg: 'RS256', typ: 'JWT' };
  const payload = { iss: saJson.client_email, scope, aud: 'https://oauth2.googleapis.com/token', exp: now + 3600, iat: now };
  const si = b64u(JSON.stringify(header)) + '.' + b64u(JSON.stringify(payload));
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(si);
  return si + '.' + b64u(signer.sign(saJson.private_key));
}
function httpsReq(opts, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(opts, res => { let d=''; res.on('data', c => d+=c); res.on('end', () => resolve({ statusCode: res.statusCode, body: d })); });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}
async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
async function httpsReqRetry(opts, body) {
  const maxTries = 4;
  for (let attempt = 0; attempt < maxTries; attempt++) {
    const res = await httpsReq(opts, body);
    if (res.statusCode !== 429 && res.statusCode < 500) return res;
    if (attempt === maxTries - 1) return res;
    await sleep(Math.min(2000 * Math.pow(2, attempt), 15000));
  }
}
async function getToken(saJson) {
  const jwt = signJWT(saJson, 'https://www.googleapis.com/auth/spreadsheets https://www.googleapis.com/auth/drive');
  const body = 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + encodeURIComponent(jwt);
  const r = await httpsReqRetry({
    hostname: 'oauth2.googleapis.com', path: '/token', method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(body) },
  }, body);
  if (r.statusCode !== 200) throw new Error('token: ' + r.statusCode + ' ' + r.body);
  return JSON.parse(r.body).access_token;
}

const params  = $('Set Parameters').first().json;
const sa      = JSON.parse(fs.readFileSync($env.N8N_GOOGLE_SA_JSON || '/files/sa.json', 'utf8'));
const tok     = await getToken(sa);
const ssId    = params.INTERNAL_SHEET_ID;
const logTab  = params.LOG_TAB_NAME;
const curTab  = params.CURSOR_TAB_NAME;

const items = $input.all().map(it => it.json);
// batch cursor is on every item (all carry the same value) — take first non-empty
let batchCursor = '';
for (const i of items) { if (i && i.batch_max_updated_iso) { batchCursor = i.batch_max_updated_iso; break; } }
const realIntents = items.filter(i => i && !i._sentinel && i.folder_id);

const nowIso = new Date().toISOString();
const logRows = [];

// ----- (a) Drive shares (or NO_EMAIL log rows) -----
for (const i of realIntents) {
  if (i._skip_reason) {
    logRows.push([nowIso, i.order_no, '', i.sku, i.folder_id, i.folder_name || '', 'NO_EMAIL', i._skip_reason]);
    continue;
  }
  const body = JSON.stringify({ role: i.role || 'reader', type: 'user', emailAddress: i.email });
  const r = await httpsReqRetry({
    hostname: 'www.googleapis.com',
    path: '/drive/v3/files/' + encodeURIComponent(i.folder_id) + '/permissions?sendNotificationEmail=true&supportsAllDrives=true',
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + tok,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  }, body);

  let status, message;
  if (r.statusCode === 200 || r.statusCode === 201) {
    status = 'SHARED';
    message = '';
  } else if ((r.statusCode === 400 || r.statusCode === 409) && /already|exist|dup/i.test(r.body)) {
    status = 'ALREADY_SHARED';
    message = 'permission exists';
  } else {
    status = 'ERROR';
    message = ('HTTP ' + r.statusCode + ': ' + r.body).slice(0, 500);
  }
  logRows.push([nowIso, i.order_no, i.email, i.sku, i.folder_id, i.folder_name || '', status, message]);
}

// ----- (b) Append to Folder Grants Log -----
let appendedRows = 0;
if (logRows.length > 0) {
  const body = JSON.stringify({ values: logRows });
  const path = '/v4/spreadsheets/' + ssId + '/values/' + encodeURIComponent(logTab) + '!A:H:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS';
  const r = await httpsReqRetry({
    hostname: 'sheets.googleapis.com', path, method: 'POST',
    headers: { 'Authorization': 'Bearer ' + tok, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
  }, body);
  if (r.statusCode !== 200) throw new Error('log append: ' + r.statusCode + ' ' + r.body);
  appendedRows = logRows.length;
}

// ----- (c) Advance cursor (only after log append succeeded) -----
let cursorAdvancedTo = '';
if (batchCursor) {
  const body = JSON.stringify({ values: [[batchCursor]] });
  const path = '/v4/spreadsheets/' + ssId + '/values/' + encodeURIComponent(curTab) + '!A2?valueInputOption=USER_ENTERED';
  const r = await httpsReqRetry({
    hostname: 'sheets.googleapis.com', path, method: 'PUT',
    headers: { 'Authorization': 'Bearer ' + tok, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
  }, body);
  if (r.statusCode !== 200) throw new Error('cursor update: ' + r.statusCode + ' ' + r.body);
  cursorAdvancedTo = batchCursor;
}

return [{ json: {
  status: 'success',
  intents_processed: realIntents.length,
  log_rows_appended: appendedRows,
  cursor_advanced_to: cursorAdvancedTo,
  shared: logRows.filter(r => r[6] === 'SHARED').length,
  already_shared: logRows.filter(r => r[6] === 'ALREADY_SHARED').length,
  errors: logRows.filter(r => r[6] === 'ERROR').length,
  no_email: logRows.filter(r => r[6] === 'NO_EMAIL').length,
} }];
